function MinProofLength(T, a, b):
    dist[*] <- infinity ;  dist[a] <- 0 ;  Q <- queue([a])
    while Q nonempty:
        x <- Q.pop()
        if x = b: return dist[x]
        for y with T(x, y):
            if dist[y] = infinity:
                dist[y] <- dist[x] + 1 ;  Q.push(y)
    return dist[b]   # infinity => b not derivable

